#include <stdio.h> int main() { int a[10][10],i,j,r,c,sum1,sum2; printf("Enter the row and column of the matrix:"); scanf("%d%d",&r,&c); for(i=0;i<r;i++) { for(j=0;j<c;j++) { printf("Enter the element [i][j]:",i+1,j+1); scanf("%d",&a[i][j]); } } printf("The matrix is:
"); for(i=0;i<r;i++) { for(j=0;j<c;j++) { printf("%d	",a[i][j]); } printf("
"); } for(i=0;i<r;i++) { for(j=0;j<c;j++) { if(i==j) { sum1=sum1+a[i][j]; } } } for(i=0;i<r;i++) { for(j=0;j<c;j++) { if(j==c-i-1) { sum2=sum2+a[i][j]; } } } printf("The sum of diagonal from left  is %d
",sum1); printf("The sum of diagonal from right  is %d",sum2); return 0; }
